using System;using System.IO;
namespace LoopPedal {
sealed class PerformanceTimeline {
 public interface Port {float get(int target,long audio);void set(int target,long audio,float value);long cycle(int bank);long phase(int bank);double tempo();bool running();float envelope();}
 public const int CAPACITY=8192,MAX_LANES=64;
 public sealed class Lane {
  public int target,mode,count;public long audio,origin,span,phaseOffset,takeSerial;public double length=4;public float baseline;public bool enabled=true;public long touched=-999999;
  public readonly long[] times=new long[CAPACITY];public readonly float[] values=new float[CAPACITY];
  public long period(Port p){return mode==4?Math.Max(240,span):duration(p,mode,length);}
  public float at(long time,long period){if(count==0)return baseline;if(count==1)return values[0];double position=(time%period+period)%period;if(span>0){position=position*span/period;period=span;}int lo=0,hi=count;while(lo<hi){int mid=(lo+hi)/2;if(times[mid]<=position)lo=mid+1;else hi=mid;}int a=(lo+count-1)%count,b=lo%count;double ta=times[a],tb=times[b];if(b==0)tb+=period;if(position<ta)position+=period;return values[a]+(values[b]-values[a])*(float)Math.Max(0,Math.Min(1,(position-ta)/Math.Max(1,tb-ta)));}
 }
 public sealed class Mod {public int target=-1,type,polarity,seed,mode=2;public long audio;public double rate=1,depth=.2,phase;public float baseline;public bool enabled;
 public int extraCount;public int[] targets=new int[31];public long[] audios=new long[31];public float[] bases=new float[31];
 public int destinations(){return target<0?0:extraCount+1;}public int targetAt(int i){return i==0?target:targets[i-1];}public long audioAt(int i){return i==0?audio:audios[i-1];}public float baseAt(int i){return i==0?baseline:bases[i-1];}public void baseAt(int i,float value){if(i==0)baseline=value;else bases[i-1]=value;}public int index(int id,long source){for(int i=0;i<destinations();i++)if(targetAt(i)==id&&audioAt(i)==source)return i;return -1;}
 }
 public readonly Lane[] lanes=new Lane[MAX_LANES];public readonly Mod[] mods={new Mod(),new Mod(),new Mod(),new Mod()};public int count,recordMode=4;public double recordLength=4;public bool playing=true,recording,armed;public long time,recordAt,recordEnd,revision,takeSerial;public int quantum;public float envelopeSmooth;
 public PerformanceTimeline(){for(int i=0;i<4;i++)mods[i].seed=i+1;}
 public static long duration(Port p,int mode,double length){if(mode<2)return Math.Max(1,p.cycle(mode));return Math.Max(240,(long)(48000*(mode==2?60/p.tempo():1)*length));}
 public Lane find(int target,long audio){for(int i=0;i<count;i++)if(lanes[i].target==target&&lanes[i].audio==audio)return lanes[i];return null;}
 public void arm(Port p,bool quantized){stop();takeSerial++;long delay=0;if(quantized&&recordMode!=4){long cycle=Math.Max(1,p.cycle(recordMode==1?1:0)),phase=p.phase(recordMode==1?1:0);delay=(cycle-(phase%cycle+cycle)%cycle)%cycle;}recordAt=time+delay;recordEnd=recordAt+(recordMode==4?long.MaxValue-recordAt:duration(p,recordMode,recordLength));armed=delay>0;recording=!armed;revision++;}
 public void stop(){if(recording&&recordMode==4){long span=Math.Max(240,time-recordAt);for(int i=0;i<count;i++){Lane l=lanes[i];if(l.takeSerial==takeSerial){l.span=span;l.mode=4;l.length=span/48000.0;}}}recording=armed=false;revision++;}
 public void touch(Port p,int target,long audio,float value){Lane lane=find(target,audio);if(recording&&time>=recordAt&&time<recordEnd){if(lane==null){if(count>=MAX_LANES)return;lane=new Lane();lane.target=target;lane.audio=audio;lane.baseline=p.get(target,audio);lanes[count++]=lane;}if(lane.takeSerial!=takeSerial||lane.count==0){lane.mode=recordMode;lane.length=recordLength;lane.origin=recordAt;lane.takeSerial=takeSerial;lane.span=recordMode==4?Math.Max(240,time-recordAt):recordEnd-recordAt;lane.phaseOffset=recordMode<2?p.phase(recordMode)-(time-recordAt):0;lane.count=1;lane.times[0]=0;lane.values[0]=lane.baseline;}long position=time-recordAt;if(lane.count>0&&position-lane.times[lane.count-1]<240)lane.values[lane.count-1]=value;else {if(lane.count==CAPACITY){for(int i=1;i<CAPACITY/2;i++){lane.times[i]=lane.times[i*2];lane.values[i]=lane.values[i*2];}lane.count=CAPACITY/2;}lane.times[lane.count]=position;lane.values[lane.count++]=value;}revision++;}else if(lane!=null){lane.baseline=value;revision++;}if(lane!=null)lane.touched=time;foreach(Mod m in mods){int index=m.index(target,audio);if(index>=0){m.baseAt(index,value);revision++;}}}
 public void tick(Port p,int frames){if(!p.running()&&!recording&&!armed)return;time+=frames;if(armed&&time>=recordAt){armed=false;recording=true;}if(recording&&time>=recordEnd)stop();quantum+=frames;if(quantum<240)return;quantum=0;float env=p.envelope();envelopeSmooth+=(env-envelopeSmooth)*(env>envelopeSmooth?.25f:.03f);for(int i=0;i<count;i++){Lane l=lanes[i];if(recording&&recordMode==4&&l.takeSerial==takeSerial){l.span=Math.Max(240,time-recordAt);l.length=l.span/48000.0;}if(!l.enabled||!playing||recording&&l.takeSerial==takeSerial||time-l.touched<12000)continue;long phase=l.mode<2?p.phase(l.mode)-l.phaseOffset:time-l.origin;p.set(l.target,l.audio,l.at(phase,l.period(p)));}for(int slot=0;slot<4;slot++){Mod m=mods[slot];if(!m.enabled)continue;for(int at=0;at<m.destinations();at++){int target=m.targetAt(at);long audio=m.audioAt(at);bool first=true;for(int j=0;j<slot;j++)if(mods[j].enabled&&mods[j].index(target,audio)>=0)first=false;if(!first)continue;Lane lane=find(target,audio);float value=lane!=null&&lane.enabled&&playing?lane.at(lane.mode<2?p.phase(lane.mode)-lane.phaseOffset:time-lane.origin,lane.period(p)):m.baseAt(at);double modulation=0;foreach(Mod n in mods)if(n.enabled&&n.index(target,audio)>=0)modulation+=LfoMath.value(n,time,duration(p,n.mode,n.rate),envelopeSmooth)*n.depth;p.set(target,audio,(float)Math.Max(0,Math.Min(1,value+modulation)));}}}
 public bool assign(Port port,int slot,int target,long audio){if(slot<0||slot>=4||!validTarget(target))return false;Mod m=mods[slot];if(m.index(target,audio)>=0){m.enabled=true;return true;}if(m.destinations()>=32)return false;float value=baseline(target,audio,port.get(target,audio));if(m.target<0){m.target=target;m.audio=audio;m.baseline=value;}else{int i=m.extraCount++;m.targets[i]=target;m.audios[i]=audio;m.bases[i]=value;}m.enabled=true;revision++;return true;}
 public void restore(Port p,Mod m){for(int i=0;i<m.destinations();i++)p.set(m.targetAt(i),m.audioAt(i),m.baseAt(i));}
 public void unlink(Port p,Mod m,int index){if(index<0||index>=m.destinations())return;p.set(m.targetAt(index),m.audioAt(index),m.baseAt(index));if(index==0){if(m.extraCount==0){m.target=-1;m.enabled=false;revision++;return;}m.target=m.targets[0];m.audio=m.audios[0];m.baseline=m.bases[0];index=1;}for(int i=index-1;i<m.extraCount-1;i++){m.targets[i]=m.targets[i+1];m.audios[i]=m.audios[i+1];m.bases[i]=m.bases[i+1];}m.extraCount--;revision++;}
 public void restart(){stop();time=0;for(int i=0;i<count;i++){lanes[i].origin=0;lanes[i].phaseOffset=0;lanes[i].touched=-999999;}}
 public void clear(Port p){for(int i=0;i<count;i++)p.set(lanes[i].target,lanes[i].audio,lanes[i].baseline);foreach(Mod m in mods){restore(p,m);m.enabled=false;m.target=-1;m.extraCount=0;}count=0;stop();}
 public float baseline(int target,long audio,float fallback){Lane l=find(target,audio);if(l!=null)return l.baseline;foreach(Mod m in mods)if(m.enabled){int i=m.index(target,audio);if(i>=0)return m.baseAt(i);}return fallback;}
 public void write(BinaryWriter d){write(d,3);}public void writeV2(BinaryWriter d){write(d,2);}public void writeLegacy(BinaryWriter d){write(d,0);}public void writeV1(BinaryWriter d){write(d,1);}void write(BinaryWriter d,int format){bool modern=format>0;if(modern){d.Write((byte)127);d.Write((byte)format);}d.Write(playing);d.Write(recordMode);d.Write(recordLength);d.Write(count);for(int i=0;i<count;i++){Lane l=lanes[i];d.Write(l.target);d.Write(l.audio);d.Write(recording&&recordMode==4&&l.takeSerial==takeSerial?Math.Max(240,time-recordAt):l.span);d.Write(l.phaseOffset);d.Write(l.mode);d.Write(recording&&recordMode==4&&l.takeSerial==takeSerial?Math.Max(240,time-recordAt)/48000.0:l.length);d.Write(l.baseline);d.Write(l.enabled);d.Write(l.count);for(int j=0;j<l.count;j++){if(modern)d.Write(l.times[j]);else d.Write((int)l.times[j]);d.Write(l.values[j]);}}foreach(Mod m in mods){d.Write(m.target);d.Write(m.audio);d.Write(m.type);d.Write(m.mode);d.Write(m.rate);d.Write(m.depth);d.Write(m.baseline);d.Write(m.enabled);if(format>=2){d.Write(m.polarity);d.Write(m.phase);}if(format>=3){d.Write(m.extraCount);for(int i=0;i<m.extraCount;i++){d.Write(m.targets[i]);d.Write(m.audios[i]);d.Write(m.bases[i]);}}}}
 public static PerformanceTimeline read(BinaryReader d){PerformanceTimeline t=new PerformanceTimeline();int first=d.ReadByte();bool modern=first==127;int format=modern?d.ReadByte():0;if(modern&&(format<1||format>3)||!modern&&first>1)throw new IOException("Unsupported automation format");t.playing=modern?d.ReadBoolean():first!=0;t.recordMode=d.ReadInt32();t.recordLength=d.ReadDouble();t.count=d.ReadInt32();if(t.count<0||t.count>MAX_LANES||t.recordMode<0||t.recordMode>4||!finite(t.recordLength)||t.recordLength<=0||t.recordLength>600)throw new IOException("Invalid automation");for(int i=0;i<t.count;i++){Lane l=new Lane();t.lanes[i]=l;l.target=d.ReadInt32();l.audio=d.ReadInt64();l.span=d.ReadInt64();l.phaseOffset=d.ReadInt64();l.mode=d.ReadInt32();l.length=d.ReadDouble();l.baseline=d.ReadSingle();l.enabled=d.ReadBoolean();l.count=d.ReadInt32();if(!validTarget(l.target)||l.span<0||l.mode!=4&&l.span>86400000||l.count<0||l.count>CAPACITY||l.mode<0||l.mode>4||!finite(l.length)||l.length<=0||l.mode!=4&&l.length>600||!finite(l.baseline))throw new IOException("Invalid automation lane");for(int j=0;j<l.count;j++){l.times[j]=modern?d.ReadInt64():d.ReadInt32();l.values[j]=d.ReadSingle();if(l.times[j]<0||j>0&&l.times[j]<l.times[j-1]||!finite(l.values[j]))throw new IOException("Invalid automation point");}}foreach(Mod m in t.mods){m.target=d.ReadInt32();m.audio=d.ReadInt64();m.type=d.ReadInt32();m.mode=d.ReadInt32();m.rate=d.ReadDouble();m.depth=d.ReadDouble();m.baseline=d.ReadSingle();m.enabled=d.ReadBoolean();m.polarity=format>=2?d.ReadInt32():m.type==2?1:0;m.phase=format>=2?d.ReadDouble():0;if(m.polarity<0||m.polarity>2||!finite(m.phase)||m.phase<0||m.phase>1||m.target!=-1&&!validTarget(m.target)||m.type<0||m.type>5||m.mode<2||m.mode>3||!finite(m.rate)||m.rate<=0||m.rate>600||!finite(m.depth)||Math.Abs(m.depth)>1||!finite(m.baseline))throw new IOException("Invalid modulation");if(format>=3){m.extraCount=d.ReadInt32();if(m.extraCount<0||m.extraCount>31||m.extraCount>0&&m.target<0)throw new IOException("Invalid destinations");for(int i=0;i<m.extraCount;i++){int id=d.ReadInt32();long audio=d.ReadInt64();float value=d.ReadSingle();for(int j=0;j<=i;j++)if(m.targetAt(j)==id&&m.audioAt(j)==audio)throw new IOException("Duplicate destination");if(!validTarget(id)||!finite(value))throw new IOException("Invalid destination");m.targets[i]=id;m.audios[i]=audio;m.bases[i]=value;}}}return t;}
 public static bool validTarget(int target){return target==300||target>=100&&target<148||target==200||target==202||target==205||target==218||target>=1000&&target<1013&&(target-1000)%8<5;}
 public static bool finite(double x){return !Double.IsNaN(x)&&!Double.IsInfinity(x);}
 public PerformanceTimeline copy(){using(var bytes=new MemoryStream()){var writer=new BinaryWriter(bytes);write(writer);writer.Flush();bytes.Position=0;return read(new BinaryReader(bytes));}}
}
}
